interface Score {
    int BONUS = 5;
    int get();
}
class Quiz implements Score {
    int pt;
    Quiz(int pt) { this.pt = pt; }
    public int get() { return pt + BONUS; }
}
class Exam extends Quiz {
    Exam(int pt) { super(pt * 2); }
    public int get() { return super.get() * 10; }
}
class Main {
    public static void main(String[] args) {
        Score[] s = { new Quiz(3), new Exam(4) };
        int t = 0;
        for (Score x : s) {
            t += x.get();
        }
        System.out.print(t);
    }
}

